def process(fraud_data) -> pd.DataFrame:
    df = fraud_data.dropna(how='all').drop_duplicates().reset_index(drop=True)
    col_names = df.columns.tolist()
    payment_col = col_names[0]
    amount_col = col_names[2]

    df = df[df[payment_col].notna()].reset_index(drop=True)
    df = df[~df[payment_col].str.contains('Payment Method|Reports|Source|Total|#', na=False, regex=True)]

    def parse_amount(val):
        if pd.isna(val):
            return None
        val = str(val).replace('$', '').replace('M', '').replace(',', '').strip()
        try:
            return float(val)
        except:
            return None

    df['amount_millions'] = df[amount_col].apply(parse_amount)
    df = df[df['amount_millions'].notna()]
    return df[[payment_col, 'amount_millions']]
